[tikz]
\begin{tikzpicture}[every node/.style={font=\large}, x=1.1cm, y=1.1cm]
\fill[gray!35, domain=1:3, variable=\y] (0,1) -- plot ({0.4*\y*\y+0.3},{\y}) -- (0,3) -- cycle;
\draw[->] (-1,0) -- (5,0) node[right] {$x$};
\draw[->] (0,-0.7) -- (0,4.2) node[above] {$y$};
\draw[thick, <->, domain=0.2:3.5, smooth, samples=100, variable=\y] plot ({0.4*\y*\y+0.3},{\y});
\draw[dashed] (0,1) -- (0.7,1);
\draw[dashed] (0,3) -- (3.9,3);
\node[left] at (0,1) {$c$};
\node[left] at (0,3) {$d$};
\node[right] at (3.6,1.9) {$x=g(y)$};
\end{tikzpicture}
[/tikz]

